"""Page arithmetic for list pages."""


def _check_items_and_size(total_items, per_page):
    if per_page < 1:
        raise ValueError("per_page must be at least 1")
    if total_items < 0:
        raise ValueError("total_items must not be negative")


def page_count(total_items, per_page):
    """Number of pages needed for the items. Zero items is one page."""
    _check_items_and_size(total_items, per_page)
    return max(1, -(-total_items // per_page))


def _check_page(total_items, per_page, page):
    pages = page_count(total_items, per_page)
    if page < 1 or page > pages:
        raise ValueError("no such page")
    return pages


def page_slice(total_items, per_page, page):
    """(start, end) indexes of the items on a page. Pages are numbered from 1.

    items[start:end] is the page; the last page may be short.
    """
    _check_page(total_items, per_page, page)
    start = (page - 1) * per_page
    end = min(start + per_page, total_items)
    return start, end


def page_window(total_items, per_page, page, size=5):
    """Page numbers to show in the pager, centred on the current page.

    Returns `size` consecutive page numbers (or all pages if there are fewer).
    With an even size the extra page goes after the current one. The window is
    shifted to stay within 1..page_count near the first or last page.
    """
    if size < 1:
        raise ValueError("size must be at least 1")
    pages = _check_page(total_items, per_page, page)
    width = min(size, pages)
    first = page - (width - 1) // 2
    first = max(1, min(first, pages - width + 1))
    return list(range(first, first + width))
